 static Keys NormalizeShortcut(Keys key){int code=(int)(key&Keys.KeyCode);if(code>=96&&code<=105)return (key&Keys.Modifiers)|(Keys)(code-48);return key;}
 static string KeyLabel(Keys key){if(key==Keys.None)return "Sem atalho";Keys code=key&Keys.KeyCode;string label=code==Keys.Space?"Espaço":code==Keys.Left?"←":code==Keys.Right?"→":code==Keys.Up?"↑":code==Keys.Down?"↓":code==Keys.Back?"Backspace":code==Keys.OemOpenBrackets?"[":code==Keys.OemCloseBrackets?"]":new KeysConverter().ConvertToString(code);return ((key&Keys.Control)!=0?"Ctrl+":"")+((key&Keys.Alt)!=0?"Alt+":"")+((key&Keys.Shift)!=0?"Shift+":"")+label;}
 void InitShortcuts(){shortcuts=DefaultShortcuts();try{var saved=json.Deserialize<Dictionary<string,int>>(File.ReadAllText(ShortcutPath));var used=new HashSet<Keys>();foreach(var item in shortcuts){int key;if(saved.TryGetValue(item.Id,out key))item.Key=NormalizeShortcut((Keys)key);if(item.Key!=Keys.None&&!used.Add(item.Key))item.Key=Keys.None;}}catch{}}
 bool DispatchShortcut(Keys key,bool repeat){key=NormalizeShortcut(key);foreach(var item in shortcuts)if(item.Key!=Keys.None&&item.Key==key){if(!repeat||item.Id.EndsWith("-up")||item.Id.EndsWith("-down")||item.Id.StartsWith("seek-"))InvokeShortcut(item.Id);return true;}return false;}
 void InvokeShortcut(string id){string[] picture={"contrast","brightness","gamma","saturation"};foreach(string property in picture)if(id==property+"-down"||id==property+"-up"){int digit=Array.IndexOf(picture,property)*2+(id.EndsWith("-up")?2:1);Send("script-message","fua-user-shortcut",digit.ToString());return;}
 switch(id){case "pause":Send("cycle","pause");break;case "seek-back":Send("seek","-5");break;case "seek-forward":Send("seek","5");break;case "seek-back-large":Send("seek","-30");break;case "seek-forward-large":Send("seek","30");break;
 case "volume-up":Send("set","volume",Math.Min(100,Number("volume")+5).ToString(System.Globalization.CultureInfo.InvariantCulture));break;case "volume-down":Send("set","volume",Math.Max(0,Number("volume")-5).ToString(System.Globalization.CultureInfo.InvariantCulture));break;case "mute":Send("cycle","mute");break;
 case "fullscreen":case "fullscreen-alt":ToggleFull();break;case "back":if(full)ToggleFull();else ShowLibrary();break;case "audio":Send("script-message","fua-open-tracks","audio");break;case "subtitle":Send("script-message","fua-open-tracks","sub");break;case "subtitle-toggle":Send("cycle","sub-visibility");break;
 case "subtitle-earlier":case "subtitle-later":
  double delay=Math.Round(Number("sub-delay")+(id=="subtitle-later"?.1:-.1),2);
  Send("set","sub-delay",delay.ToString(System.Globalization.CultureInfo.InvariantCulture));
  Send("show-text","Legenda: "+delay.ToString("+0.0;-0.0;0.0")+" s");
  break;
 case "speed-down":case "speed-up":Send("set","speed",Math.Max(.25,Math.Min(3,Math.Round(Number("speed")+(id=="speed-up"?.1:-.1),2))).ToString(System.Globalization.CultureInfo.InvariantCulture));break;case "speed-reset":Send("set","speed","1");break;case "screenshot":HandleUi("screenshot");break;case "rtx":HandleUi("rtx");break;case "information":Send("script-message","fua-stats-cycle");break;
 case "image-reset":foreach(string property in picture)Send("set",property,"0");break;case "shortcuts":EditShortcuts();break;case "open":using(var dialog=new OpenFileDialog()){dialog.Filter="Vídeos|*.mkv;*.mp4;*.avi;*.webm;*.mov|Todos|*.*";if(dialog.ShowDialog(this)==DialogResult.OK)Open(dialog.FileName,0);}break;
 }}
